export const chartTypes=[['bar','柱状图'],['line','折线图'],['scatter','散点图'],['grouped','分组柱状图']];
export function exampleChart(){return {title:'实验方案对比（示例）',projectId:'',headers:['类别','方案 A','方案 B'],rows:[['样本一','18','22'],['样本二','25','28'],['样本三','21','26'],['样本四','30','32']],type:'grouped',series:0,xLabel:'样本类别',yLabel:'指标值',unit:'',palette:'blue',fontSize:14,width:1600,height:1000,legend:true,grid:true,example:true};}
export function numberCell(v,label){const s=String(v??'').trim();if(!s||!/^[-+]?(?:\d+\.?\d*|\.\d+)(?:e[-+]?\d+)?$/i.test(s)||!Number.isFinite(Number(s))||Math.abs(Number(s))>1e12)throw new Error(label+' 必须是绝对值不超过 10¹² 的有限数值；空值不按 0 处理。');return Number(s);}
export function validateData(chart){const {headers,rows}=chart;if(!Array.isArray(headers)||headers.length<2||headers.length>6)throw new Error('需要类别或 X 列，加 1–5 个数值系列。');if(headers.some(h=>!String(h).trim()||String(h).length>40)||new Set(headers.map(h=>String(h).trim())).size!==headers.length)throw new Error('列名称不能为空、重复或超过 40 字。');if(!Array.isArray(rows)||!rows.length||rows.length>200)throw new Error('请填写 1–200 行数据。');const points=rows.map((row,i)=>{if(!Array.isArray(row)||row.length!==headers.length)throw new Error(`第 ${i+1} 行列数与表头不一致。`);if(!String(row[0]).trim()||String(row[0]).length>40)throw new Error(`第 ${i+1} 行类别不能为空或超过 40 字。`);return {label:String(row[0]),x:chart.type==='scatter'?numberCell(row[0],`第 ${i+1} 行 X`):i,values:row.slice(1).map((v,j)=>numberCell(v,`第 ${i+1} 行「${headers[j+1]}」`))};});return points;}
export function parseTable(text){if(typeof text!=='string'||text.length>250000)throw new Error('表格最多 250,000 字符。');text=text.replace(/^\uFEFF/,'');let quote=false,sep=',';for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"')i++;else quote=!quote;}else if(!quote&&c==='\t'){sep='\t';break;}else if(!quote&&(c==='\n'||c==='\r'))break;}let result=[],row=[],cell='',quoted=false,closed=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'){if(text[i+1]==='"'){cell+='"';i++;}else{quoted=false;closed=true;}}else cell+=c;}else if(c==='"'){if(cell||closed)throw new Error('引号位置不正确，请使用标准 CSV。');quoted=true;}else if(c===sep){row.push(cell);cell='';closed=false;}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.length>1||row.some(v=>v!==''))result.push(row);row=[];cell='';closed=false;}else{if(closed)throw new Error('CSV 结束引号后只能是分隔符或换行。');cell+=c;}}if(quoted)throw new Error('CSV 引号未闭合。');row.push(cell);if(row.length>1||row.some(v=>v!==''))result.push(row);if(result.length<2)throw new Error('第一行需要表头，后面至少一行数据。');const chart={headers:result[0].map(v=>v.trim()),rows:result.slice(1),type:'grouped'};validateData(chart);return chart;}
export function csvText(chart){validateData(chart);const safe=v=>{let t=String(v);if(/^[\s]*[=+@-]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"';};return '\uFEFF'+[chart.headers.map(safe).join(','),...chart.rows.map(row=>[safe(row[0]),...row.slice(1).map(v=>String(numberCell(v,'数值')))].join(','))].join('\r\n');}
export function domain(values,includeZero=true){let min=Math.min(...values),max=Math.max(...values);if(includeZero){min=Math.min(0,min);max=Math.max(0,max);}if(min===max){const pad=Math.max(1,Math.abs(min)*.1);min-=pad;max+=pad;}if(max-min<1e-280){min=Math.min(min,-1e-280);max=Math.max(max,1e-280);}const span=max-min,step=10**Math.floor(Math.log10(span/5));const ratio=span/5/step,nice=(ratio<=1?1:ratio<=2?2:ratio<=5?5:10)*step;const lo=Math.floor(min/nice)*nice,hi=Math.ceil(max/nice)*nice,ticks=[];for(let i=0;i<=Math.round((hi-lo)/nice);i++)ticks.push(Number((lo+i*nice).toPrecision(12)));return {min:lo,max:hi,ticks};}
const xml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const palettes={blue:['#2F6BFF','#1DB7AF','#916AE7','#EF9D3F','#7188A8'],mono:['#233D60','#57769C','#7F9FC6','#AAC0DD','#CDD9EA'],nature:['#168E83','#4C79AF','#AD9254','#8C77AB','#7B9C70']};
export function renderChart(chart){const points=validateData(chart);if(!chartTypes.some(([id])=>id===chart.type))throw new Error('请选择支持的图表类型。');if(!chart.title?.trim()||chart.title.length>120)throw new Error('图表标题需要 1–120 字。');const width=Number(chart.width),height=Number(chart.height),f=Number(chart.fontSize);if(![1200,1600,2400].includes(width)||!Number.isFinite(height)||height!==width*.625||![12,14,16,18].includes(f))throw new Error('导出尺寸或字号不正确。');const series=Math.max(0,Math.min(chart.headers.length-2,Number(chart.series)||0)),indices=chart.type==='bar'?[series]:chart.headers.slice(1).map((_,i)=>i),colors=palettes[chart.palette]||palettes.blue,dy=domain(points.flatMap(p=>indices.map(i=>p.values[i]))),dx=chart.type==='scatter'?domain(points.map(p=>p.x),false):null,L=105,R=950,T=105,B=475,W=R-L,H=B-T,y=v=>B-(v-dy.min)/(dy.max-dy.min)*H,x=p=>dx?L+(p.x-dx.min)/(dx.max-dx.min)*W:L+(p.x+.5)*W/points.length,fmt=n=>Math.abs(n)>=1e6||Math.abs(n)>0&&Math.abs(n)<.001?n.toExponential(1):String(Number(n.toPrecision(8))),text=(xx,yy,t,extra='')=>`<text x="${xx}" y="${yy}" ${extra}>${xml(t)}</text>`;let svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 1000 625" role="img" aria-label="${xml(chart.title)}"><title>${xml(chart.title)}</title><desc>${xml(chart.example?'示例数据，不代表真实研究。':'图表来自用户输入数据。')} ${xml(chart.headers.join(' / '))}</desc><rect width="1000" height="625" fill="white"/><defs><clipPath id="plot"><rect x="${L-2}" y="${T-4}" width="${W+4}" height="${H+8}"/></clipPath></defs><g font-family="Arial,Microsoft YaHei,sans-serif" font-size="${f}" fill="#526986">${text(500,47,chart.title,'text-anchor="middle" font-size="24" font-weight="bold" fill="#203659"')}${chart.example?text(R,76,'示例数据','text-anchor="end" fill="#2F6BFF"'):''}`;
for(const tick of dy.ticks){const yy=y(tick);if(chart.grid)svg+=`<path d="M${L} ${yy}H${R}" stroke="#E3EAF4" stroke-dasharray="4 4"/>`;svg+=text(L-14,yy+5,fmt(tick),'text-anchor="end"');}svg+=`<path d="M${L} ${T}V${B}H${R}" fill="none" stroke="#AEBFD6"/><path d="M${L} ${y(0)}H${R}" stroke="#B7C6D9"/>`;const labelStep=Math.max(1,Math.ceil(points.length/12));if(dx){for(const tick of dx.ticks)svg+=text(L+(tick-dx.min)/(dx.max-dx.min)*W,B+28,fmt(tick),'text-anchor="middle"');}else for(const [i,p]of points.entries()){if(i%labelStep===0)svg+=text(x(p),B+28,p.label.length>10?p.label.slice(0,9)+'…':p.label,'text-anchor="middle"');}
svg+='<g clip-path="url(#plot)">';for(const k of indices){const color=colors[k%colors.length];if(chart.type==='bar'||chart.type==='grouped'){const band=W/points.length,bw=band*.7/indices.length;for(const p of points){const yy=y(p.values[k]),zero=y(0),xx=x(p)-band*.35+indices.indexOf(k)*bw;svg+=`<rect data-value="${p.values[k]}" x="${xx}" y="${Math.min(yy,zero)}" width="${Math.max(.3,bw-2)}" height="${Math.abs(yy-zero)}" fill="${color}"><title>${xml(p.label+' / '+chart.headers[k+1]+': '+p.values[k])}</title></rect>`;if(points.length<=12)svg+=text(xx+bw/2,p.values[k]>=0?yy-7:yy+19,fmt(p.values[k]),'text-anchor="middle" font-size="12"');}}else{if(chart.type==='line')svg+=`<polyline points="${points.map(p=>x(p)+','+y(p.values[k])).join(' ')}" fill="none" stroke="${color}" stroke-width="2.5"/>`;for(const p of points)svg+=`<circle data-value="${p.values[k]}" cx="${x(p)}" cy="${y(p.values[k])}" r="4" fill="${color}"><title>${xml(p.label+' / '+chart.headers[k+1]+': '+p.values[k])}</title></circle>`;}}
svg+='</g>';svg+=text(500,545,chart.xLabel||chart.headers[0],'text-anchor="middle"')+text(28,290,(chart.yLabel||'数值')+(chart.unit?'（'+chart.unit+'）':''),'text-anchor="middle" transform="rotate(-90 28 290)"');if(chart.legend)for(const [i,k]of indices.entries()){const xx=100+i*170;svg+=`<rect x="${xx}" y="573" width="12" height="12" fill="${colors[k%colors.length]}"/>`+text(xx+20,584,chart.headers[k+1].length>12?chart.headers[k+1].slice(0,11)+'…':chart.headers[k+1]);}svg+=text(R,613,'PaperKnow · '+(chart.example?'示例':'用户数据'),'text-anchor="end" font-size="10" fill="#8B9BB1"');return svg+'</g></svg>';}
